def fetch_package_info(package: str) -> Dict[str, Any]:
    url = f"https://pypi.org/pypi/{package}/json"
    try:
        response = requests.get(url, timeout=5)
        if response.status_code == 200:
            data = response.json()
            return {
                "package": package,
                "version": data["info"]["version"],
