import sys
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import json
import os

def fetch_package_info(package):
    url = f"https://pypi.org/pypi/{package}/json"
    try:
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            data = response.json()
            return {"package": package, "version": data["info"]["version"], "summary": data["info"]["summary"]}
        else:
            return {"package": package, "error": f"HTTP {response.status_code}"}
    except Exception as e:
        return {"package": package, "error": f"HTTP error: {str(e)}"}

def process_input(input_path, output_path):
    with open(input_path, 'r') as f:
        packages = [line.strip() for line in f if line.strip()]

    with ThreadPoolExecutor(max_workers=3) as executor:
        futures = {executor.submit(fetch_package_info, pkg): pkg for pkg in packages}
        results = []
        for future in as_completed(futures):
            results.append(future.result())

    with open(output_path, 'w') as f:
        for result in results:
            json.dump(result, f)
            f.write('\n')

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python pkg_info.py <input_file> <output_file>", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]

    if not os.path.exists(input_file):
        print(f"Error: Input file '{input_file}' does not exist.", file=sys.stderr)
        sys.exit(1)

    process_input(input_file, output_file)
    sys.exit(0)

import argparse
import json
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import quote

def fetch_package_info(package):
    url = f"https://pypi.org/pypi/{quote(package)}/json"
    try:
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            data = response.json()
            return {
                "package": package,
                "version": data.get("info", {}).get("version"),
                "summary": data.get("info", {}).get("summary")
            }
        else:
            return {"package": package, "error": f"HTTP {response.status_code}"}
    except Exception as e:
        return {"package": package, "error": f"Request failed: {str(e)}"}

def process_packages(input_path, output_path):
    with open(input_path, 'r') as f:
        packages = [line.strip() for line in f if line.strip()]

    with open(output_path, 'w') as out:
        with ThreadPoolExecutor(max_workers=3) as executor:
            futures = {executor.submit(fetch_package_info, pkg): pkg for pkg in packages}
            for future in as_completed(futures):
                result = future.result()
                out.write(json.dumps(result) + '\n')

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description='Fetch package metadata from PyPI.')
    parser.add_argument('input_file', help='Input file containing package names')
    parser.add_argument('output_file', help='Output file for JSON Lines results')
    args = parser.parse_args()
    process_packages(args.input_file, args.output_file)
